// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 blockNum, uint256 timestamp, address sender) public {
        vm.assume(timestamp > c.pastBlockTime());
        vm.assume(sender != address(0));
        vm.assume(blockNum > 0);

        vm.roll(blockNum);
        vm.warp(timestamp);

        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        if (ok && (blockNum % 15 != 0)) {
            assertTrue(c.pastBlockTime() == timestamp);
        }
    }
}
